{
  "name": "digipanel-node-app",
  "version": "1.0.0",
  "private": true,
  "description": "Node.js application provisioned by DigiPanel",
  "main": "server.js",
  "scripts": {
    "start": "node server.js"
  },
  "engines": {
    "node": ">=20"
  }
}

"use strict";

const http = require("node:http");
const fs = require("node:fs");
const path = require("node:path");

try {
  if (typeof process.loadEnvFile === "function") {
    process.loadEnvFile(path.join(__dirname, ".env"));
  }
} catch (error) {
  if (error && error.code !== "ENOENT") {
    console.error("environment file error:", error.message);
  }
}

const port = Number(process.env.PORT || 8080);
const host = process.env.HOST || "127.0.0.1";
const appURL = process.env.APP_URL || `http://${host}:${port}`;
const startedAt = new Date();

const server = http.createServer((request, response) => {
  if (request.url === "/healthz") {
    response.writeHead(200, { "content-type": "application/json; charset=utf-8" });
    response.end(JSON.stringify({ status: "ok", uptimeSeconds: Math.floor(process.uptime()) }));
    return;
  }
  if (request.url === "/" || request.url === "/index.html") {
    response.writeHead(200, { "content-type": "text/html; charset=utf-8" });
    response.end(`<!doctype html>
<html lang="en">
<head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>Application ready</title></head>
<body style="font-family:system-ui,sans-serif;max-width:42rem;margin:4rem auto;padding:0 1rem">
<h1>Application ready</h1>
<p>This Node.js application was provisioned by DigiPanel.</p>
<dl>
<dt>Public URL</dt><dd>${appURL}</dd>
<dt>Process started</dt><dd>${startedAt.toISOString()}</dd>
<dt>Node.js</dt><dd>${process.version}</dd>
</dl>
<p>Replace <code>server.js</code> with your application entry point. Process supervision is managed from Runtimes &amp; Apps.</p>
</body>
</html>`);
    return;
  }
  response.writeHead(404, { "content-type": "text/plain; charset=utf-8" });
  response.end("not found\n");
});

server.listen(port, host, () => {
  console.log(`listening on http://${host}:${port}`);
});

for (const signal of ["SIGINT", "SIGTERM"]) {
  process.on(signal, () => server.close(() => process.exit(0)));
}
